class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        path, found = [], []
        count = 0

        def dfs():
            nonlocal count
            if found:
                return                       # early stop once the k-th string is found
            if len(path) == n:
                count += 1                   # leaves arrive in lexicographic order
                if count == k:
                    found.append(''.join(path))
                return
            for ch in 'abc':                 # increasing order -> lexicographic leaves
                if path and path[-1] == ch:
                    continue                 # no equal adjacent letters
                path.append(ch)
                dfs()
                path.pop()

        dfs()                                # visits at most k leaves, each path O(n) deep
        return found[0] if found else ''
